(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.015+t*0.4)*20 + Math.cos(y*0.012-t*0.3)*15 + Math.sin((x+y)*0.008+t*0.2)*10;
  const wy = Math.cos(y*0.015-t*0.35)*20 + Math.sin(x*0.013+t*0.45)*15 + Math.cos((x-y)*0.009-t*0.25)*10;
  const sx = x + wx, sy = y + wy;
  const wells = [
    [160+Math.sin(t*0.5)*100,80+Math.cos(t*0.35)*50,9000],
    [320+Math.cos(t*0.45)*100,160+Math.sin(t*0.6)*50,7000],
    [240+Math.sin(t*0.3+2)*130,120+Math.cos(t*0.45+1)*80,12000],
    [100+Math.cos(t*0.7+1)*70,190+Math.sin(t*0.55+3)*50,5500],
    [380+Math.sin(t*0.4+4)*80,50+Math.cos(t*0.8+2)*60,8000],
