    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.09,3.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.11,2.2],
    [200+Math.sin(t*0.65+3)*60,40+Math.cos(t*0.75)*40,0.13,2.6],
